// Create an item handler (inventory)
public class MyInventory extends ItemStackHandler {
    private static final int SLOTS = 9;

    public MyInventory() {
        super(SLOTS);
    }

    @Override
    public void setStackInSlot(int slot, ItemStack stack) {
        super.setStackInSlot(slot, stack);
        // Add custom logic when item changes
    }
}

// Use with capabilities
public class MyBlockEntity extends BlockEntity {
    private final ItemStackHandler inventory = new MyInventory();

    @Override
    public <T> LazyOptional<T> getCapability(Capability<T> cap, Direction side) {
        return ForgeCapabilities.ITEM_HANDLER.orEmpty(cap, LazyOptional.of(() -> inventory));
    }
}

